}

export function isNode(v) {
  return v && typeof v === 'object' && v.type;
}

function makeMethod(name, fnNode) {
  return {
    name,
    startLine: fnNode.loc.start.line,
    endLine: fnNode.loc.end.line,
    node: fnNode,
