Case A (all pass): lr = { state: 'CHANGES_REQUESTED', commitId: 'old' }; item.pr = { headSha: 'new', mergeState: 'CLEAN', state: 'open', mergeable: true }; q = { reviewStale: true, staleVerdict: true, latestVerdict: ['CHANGES_REQUESTED'], threadsResolved: true }.

