cat >> js/unit-tests/test_smGithubSource.js << 'EOF'

// ── gh-1221 CRAP characterization: matchesGuards probe order across the ──────
// composite split. The guard chain short-circuits; the LAZY PROVIDER PROBES
// (lastReview / latestVerdictRecord / reviewThreads) are side-effecting
// (verdict memo, label cache) and their relative order is contract — the
// composites must preserve both, exactly like the flat guard table did.
suite('sm github source — matchesGuards probe order (gh-1221 composite split)', function () {

    function orderLoad() {
        var smAsyncMod = loadModule('js/common/smAsync.js', makeRequire({
            './common/smProvider.js': { createSmProvider: function () { return null; } }
        }), {});
        return loadModule('js/sm/sources/githubSource.js', makeRequire({
            '../../common/machineAuthor.js': loadModule('js/common/machineAuthor.js', makeRequire({}), {}),
            '../../common/smProvider.js': { createSmProvider: function () { return null; } },
            '../../common/smAsync.js': smAsyncMod,
            '../../common/mutexRegistry.js': loadModule('js/common/mutexRegistry.js', makeRequire({}), {}),
            '../../common/guestTransplant.js': loadModule('js/common/guestTransplant.js', makeRequire({
                './machineAuthor.js': loadModule('js/common/machineAuthor.js', makeRequire({}), {})
            }), {})
        }), {});
    }

    function recordingProvider(calls, lastReview, verdictRecord) {
        return {
            lastReview: function (n) { calls.push('lastReview'); return lastReview; },
            latestVerdictRecord: function (n, sha, opts) {
                calls.push('latestVerdictRecord'); return verdictRecord;
            },
            reviewThreads: function (n) {
                calls.push('reviewThreads'); return { total: 1, unresolved: 0 };
            }
        };
    }

    function headItem() {
        return { prNumber: 901, labels: [],
                 pr: { state: 'open', mergeState: 'CLEAN', mergeable: true, headSha: 'new' } };
    }

    test('every lazy probe runs in contract order: review → review → verdict record → threads', function () {
        var calls = [];
        var gt = orderLoad();
        var provider = recordingProvider(calls,
            { state: 'CHANGES_REQUESTED', commitId: 'old' },
            { record: { verdict: 'CHANGES_REQUESTED' } });
        var ok = gt.matchesGuards(headItem(),
            { query: { type: 'pr', reviewStale: true, staleVerdict: true,
                       latestVerdict: ['CHANGES_REQUESTED'], threadsResolved: true } },
            provider, null, 'o', { owner: 'o', repo: 'r' });
        assert.equal(ok, true, 'all probes agree — the item matches');
        assert.deepEqual(calls,
            ['lastReview', 'lastReview', 'latestVerdictRecord', 'reviewThreads'],
            'probe order and multiplicity are contract (reviewStale + staleVerdict both read lastReview)');
    });

    test('a failed review guard short-circuits BEFORE the verdict-record and threads probes', function () {
        var calls = [];
        var gt = orderLoad();
        var provider = recordingProvider(calls, null, null);
        var ok = gt.matchesGuards(headItem(),
            { query: { type: 'pr', reviewStale: true, threadsResolved: true } },
            provider, null, 'o', { owner: 'o', repo: 'r' });
        assert.equal(ok, false, 'no review on the PR → reviewStale fails');
        assert.deepEqual(calls, ['lastReview'],
            'the chain stopped after the review probes — verdict record and threads never ran');
    });

    test('a cheap pre-probe guard fail never touches the provider at all', function () {
        var calls = [];
        var gt = orderLoad();
        var provider = recordingProvider(calls, null, null);
        var item = headItem();
        item.pr.checks = 'red';
        var ok = gt.matchesGuards(item,
            { query: { type: 'pr', prChecks: ['green'], reviewStale: true, threadsResolved: true } },
            provider, null, 'o', { owner: 'o', repo: 'r' });
        assert.equal(ok, false, 'prChecks mismatch fails first');
        assert.deepEqual(calls, [], 'no provider probe is reached (the cached-issue-label fetch included)');
    });
});
EOF
